    "features_to_try": [
      {
        "feature": "Hooks",
        "one_liner": "Shell commands that auto-run at specific lifecycle events like pre-edit or post-commit.",
        "why_for_you": "You hit 'wrong_approach' friction 8 times — hooks can automatically verify you're editing source files (not deployed copies), enforce encoding headers, and validate slash command naming conventions before changes land.",
