116→/* Elevator metatags */
117→.metatagWrapper {
118→  position: absolute;
119→  bottom: 0;
120→  left: 0;
121→  right: 0;
122→  height: 30px;
123→  overflow: hidden;
124→}
125→
126→.metatagInner {
127→  display: flex;
128→  flex-wrap: wrap;
129→  gap: 8px;
130→  transform: translateY(-110%);
131→  opacity: 0;
132→  transition:
133→    transform 350ms var(--ease),
134→    opacity 250ms var(--ease);
135→}
136→
137→.card:hover .metatagInner {
138→  transform: translateY(0);
139→  opacity: 1;
