file.content:
"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import styles from "./Nav.module.css";

const NAV_LINKS = [
  { href: "/work", label: "Work" },
  { href: "/about", label: "About" },
  { href: "/thoughts", label: "Thoughts" },
] as const;

const SOCIAL_LINKS = [
  { label: "LinkedIn", href: "https://www.linkedin.com/in/jaimeibrahim/" },
  { label: "Instagram", href: "https://www.instagram.com/jaimeibrahim/" },
] as const;

export function Nav() {
  const pathname = usePathname();
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  // Close mobile menu on route change
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- Intentional: close menu on navigation
    setMobileOpen(false);
  }, [pathname]);

  useEffect(() => {
    const handler = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", handler, { passive: true });
    return () => window.removeEventListener("scroll", handler);
  }, []);

  const isActive = (href: string) => {
    if (href === "/work") return pathname === "/" || pathname.startsWith("/work");
    return pathname.startsWith(href);
  };

  return (
    <nav className={`${styles.nav} ${scrolled ? styles.navScrolled : ""}`}>
      {/* Left: nav links */}
      <div className={`${styles.links} ${styles.linksLeft}`}>
        {NAV_LINKS.map((link) => (
          <Link key={link.href} href={link.href} className={`${styles.navLink} ${isActive(link.href) ? styles.navLinkActive : ""}`}>
            {link.label}
          </Link>
        ))}
      </div>

      {/* Center: nameplate */}
      <Link href="/" className={styles.nameplate}>
        <span className={styles.hairline} />
        <span className={styles.nameplateText}>Jaime Ibrahim</span>
        <span className={styles.hairline} />
      </Link>

      {/* Right: social links */}
      <div className={`${styles.links} ${styles.linksRight}`}>
        {SOCIAL_LINKS.map((link) => (
          <a
            key={link.label}
            href={link.href}
            target="_blank"
            rel="noopener noreferrer"
            className={styles.navLink}
          >
            {link.label}
          </a>
        ))}
      </div>

      {/* Mobile menu button */}
      <button
        className={styles.mobileMenuBtn}
        onClick={() => setMobileOpen(!mobileOpen)}
        aria-label="Toggle menu"
      >
        <span
          className={styles.mobileMenuLine}
          style={{
            transform: mobileOpen ? "rotate(45deg) translate(2px, 2px)" : "none",
          }}
        />
        <span
          className={styles.mobileMenuLine}
          style={{ opacity: mobileOpen ? 0 : 1 }}
        />
        <span
          className={styles.mobileMenuLine}
          style={{
            transform: mobileOpen ? "rotate(-45deg) translate(2px, -2px)" : "none",
          }}
        />
      </button>

      {/* Mobile dropdown */}
      {mobileOpen && (
        <div className={styles.mobileDropdown}>
          {NAV_LINKS.map((link) => (
            <Link
              key={link.href}
              href={link.href}
              className={`${styles.mobileLink} ${isActive(link.href) ? styles.mobileLinkActive : ""}`}
            >
              {link.label}
            </Link>
          ))}
          <div className={styles.mobileSocials}>
            {SOCIAL_LINKS.map((link) => (
              <a
                key={link.label}
                href={link.href}
                target="_blank"
                rel="noopener noreferrer"
                className={styles.mobileSocialLink}
              >
                {link.label}
              </a>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
}

