/* --- Intro Animation Overlay --- */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: #000;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.overlay.fadeOut {
  animation: overlayFade 600ms var(--ease-out) forwards;
}

.overlay.hidden {
  display: none;
}

