export const PROJECTS: Project[] = [
  {
    slug: "battlebank", title: "Battle Bank Launch", category: "Identity",
    desc: "Visual identity for a challenger fintech brand",
    longDesc: "A group of experienced banking industry experts are launching a challenger bank. It was important to create an identity for the bank that stood out from the traditional banks. The mountains of Colorado were an inspiration for the bank and it was important to nod to that throughout the brand touchpoints. As the creative director overseeing the brand and identity of this project, I provided creative and art direction to a team of designers, illustrators and developers.",
    credits: "Creative direction",
    color: "#2D5A45", year: "2024", featured: true,
