/* Mobile */
.mobileMenuBtn {
  display: none;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  position: absolute;
  right: 20px;
  top: 50%;
  transform: translateY(-50%);
}

.mobileMenuLine {
  width: 20px;
  height: 1.5px;
  background: var(--text);
  display: block;
  transition: transform 200ms var(--ease);
}

.mobileDropdown {
  position: absolute;
  top: var(--nav-h);
  left: 0;
  right: 0;
  background: rgba(250, 250, 248, 0.97);
  backdrop-filter: blur(20px);
  padding: 16px 0;
  animation: fadeSlideUp 200ms var(--ease-out);
}

.mobileLink {
  display: block;
  width: 100%;
  text-align: left;
  padding: 12px var(--pad);
  font-size: 13px;
  font-weight: 400;
  color: var(--text);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.mobileLinkActive {
  font-weight: 500;
}

.mobileSocials {
  display: flex;
  gap: 24px;
  padding: 12px var(--pad);
}

.mobileSocialLink {
  font-size: 13px;
  font-weight: 400;
  color: var(--text);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

@media (max-width: 480px) {
  .links {
    display: none !important;
  }
  .mobileMenuBtn {
    display: flex !important;
  }
}

