file.content:
/* --- Design Tokens as CSS Custom Properties --- */
:root {
  --bg: #EEEEEC;
  --text: #1A1A1A;
  --muted: #767676;
  --muted-light: #999999;
  --accent: #D4FF00;
  --border: #E8E8E6;
  --grid-line: rgba(0,0,0,0.055);
  --grid-line-hover: rgba(0,0,0,0.08);
  --font: 'Inter', -apple-system, 'Helvetica Neue', Helvetica, sans-serif;
  --ease: cubic-bezier(0.33, 1, 0.68, 1);
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --pad: clamp(20px, 4vw, 80px);
  --max-w: 1400px;
  --nav-h: 72px;
  --img-radius: 6px;
  --row-gap: 24px;
}

/* --- Resets --- */
*, *::before, *::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6, p {
  margin: 0;

