file.content:
export type Category =
  | "Identity"
  | "Brand Design"
  | "Systems"
  | "Event Design"
  | "Motion"
  | "Case Study"
  | "Fractional CD"
  | "Cutting Room Floor";

export interface Project {
  slug: string;
  title: string;
  category: Category;
  desc: string;
  longDesc?: string;
  credits?: string;
  videoUrl?: string;
  cropPosition?: string;
  color: string;
  year: string;
  featured?: boolean;
}

export type GridRowType = "hero" | "wide-narrow" | "narrow-wide" | "triple";

export interface GridRow {
  type: GridRowType;
  slugs: string[];
  text: boolean[];
  heights: number[];
}

export interface CaseStudySection {
  heading: string;
  body: string;
  images: number;
}

export interface CaseStudy {
  sections: CaseStudySection[];
}

export interface Thought {
  slug: string;
  title: string;
  date: string;
  excerpt: string;
}

import type { Project, GridRow, CaseStudy, Thought } from "./types";

export const PROJECTS: Project[] = [
  {
    slug: "battlebank", title: "Battle Bank Launch", category: "Identity",
    desc: "Visual identity for a challenger fintech brand",
    longDesc: "A group of experienced banking industry experts are launching a challenger bank. It was important to create an identity for the bank that stood out from the traditional banks. The mountains of Colorado were an inspiration for the bank and it was important to nod to that throughout the brand touchpoints. As the creative director overseeing the brand and identity of this project, I provided creative and art direction to a team of designers, illustrators and developers.",
    credits: "Creative direction",
    color: "#2D5A45", year: "2024", featured: true,
  },
  {
    slug: "glg-brand", title: "GLG Brand Development", category: "Identity",
    desc: "Global rebrand for the world's insight network",
    longDesc: "As the creative director at GLG, I was tasked with bringing a visual system to life across every brand touchpoint. These include brand marketing campaigns, our website, digital ads, and internal programs. The main goal was to make sure the visual representation of GLG fit with the brand promise. Through color, iconography, photography and typography GLG came to life. In doing this work I built a team of talented designers and writers. Below are a few key projects that my team has created.",
    credits: "Creative direction, design",
    color: "#1E3A5F", year: "2024", featured: true,
  },
  {
    slug: "glg-video", title: "GLG Brand Manifesto Video", category: "Motion",
    desc: "Brand manifesto video for global town hall",
    longDesc: "As part of a company rebrand, I directed a brand manifesto video to be used at our global town hall. We wanted to introduce the new messaging and get the employees excited about GLG's visual evolution. I worked with the brand management team, an editor and voice over talent to bring this video to life.",
    credits: "Creative direction",
    videoUrl: "https://player.vimeo.com/video/570306596",
    color: "#2B4A70", year: "2024",
  },
  {
    slug: "glg-explainer", title: "GLG Explainer Video", category: "Motion",
    desc: "Marketing explainer for global business units",
    longDesc: "The marketing team was getting a lot of requests for campaigns that would explain how GLG worked. We decided to create an explainer video that our business units could use globally when working with new potential clients and council members.",
    credits: "Creative direction",
    videoUrl: "https://player.vimeo.com/video/910157740",
    color: "#3D5A80", year: "2024",
  },
  {
    slug: "liquidstock", title: "Liquid Stock Branding", category: "Identity",
    desc: "Fintech brand identity for equity solutions",
    longDesc: "A newly launched fintech startup was looking for a logo and identity for their brand. The company was founded in California and wanted to have their look and feel reflect their location as well as the idea of liquidity as that was what they did for their customers. The solution was a simple mark that stood out against the competition.",
    credits: "Creative direction and design",
    color: "#4A6741", year: "2023", featured: true,
  },
  {
    slug: "year-ahead", title: "The Year Ahead", category: "Event Design",
    desc: "Inaugural business summit branding",
    longDesc: "Branding for inaugural business summit that brought together senior executives, public sector officials and thought leaders from around the world to engage in conversations focused on the challenges, opportunities and trends facing them in the coming year. The brand would be seen throughout Chicago leading up to the event, across social media, apps, signage.",
    credits: "Art direction, design",
    color: "#8B4513", year: "2023", featured: true,
  },
  {
    slug: "tiaa", title: "TIAA", category: "Brand Design",
    desc: "Enterprise rebranding initiative",
    longDesc: "As part of a company-wide rebranding initiative the below are a few projects that stood out. A timeline installation, collateral pieces and a retirement project that spanned 30 years. After thirty years of compiling data on the habits of retirees TIAA published its findings we compiled a website that shares the data, videos of customer experiences and links to stories written about the findings.",
    credits: "Art direction, design",
    videoUrl: "https://player.vimeo.com/video/910195637",
    color: "#00529B", year: "2023", featured: true,
  },
  {
    slug: "bloomberg", title: "Bloomberg Video Installation", category: "Systems",
    desc: "Video installation for Bloomberg offices",
    longDesc: "A large-scale video installation created for Bloomberg's office environment, combining art direction and design to showcase the intersection of data and visual storytelling.",
    credits: "Art direction, design",
    videoUrl: "https://player.vimeo.com/video/910191569",
    color: "#1A1A1A", year: "2022", featured: true,
  },
  {
    slug: "employee-brand", title: "Employee Brand Identity", category: "Brand Design",
    desc: "Bloomberg summer picnic series branding",
    longDesc: "Bloomberg had a history of throwing a series of global summer picnics to thank the employees for all of their hard work during the year. The concept behind this particular year's summer picnic series is to celebrate the diversity and vibrance of color, combined with the energy and movement of the people. This is a visual representation of the Bloomberg employees and the company as a whole. Get in the Mix promotes joining, linking, connecting, collaborating, getting together and having fun.",
    credits: "Art direction and design",
    color: "#6B4C9A", year: "2022",
  },
  {
    slug: "opera", title: "The Metropolitan Opera", category: "Motion",
    desc: "Bloomberg sponsorship preview spot",
    longDesc: "Bloomberg was a sponsor for The Metropolitan Opera's movie theater initiative. We created this spot that focused on the combination of art and data to run as a preview before the live streaming event.",
    credits: "Art direction, design",
    videoUrl: "https://player.vimeo.com/video/910179983",
    cropPosition: "left center",
    color: "#8B2942", year: "2022",
  },
  {
    slug: "construction", title: "Construction Wall", category: "Event Design",
    desc: "Environmental mural for Bloomberg pantry",
    longDesc: "Bloomberg was doing some construction in the main, famous pantry area. Because the company valued design, the facilities team came to the internal creative team to create a mural to put up for the duration of the project. I worked closely with a copywriter to develop a concept that would be bold, clever and informative. There were quotes all along the wall about progress, waiting and having patience.",
    credits: "Design",
    color: "#7A7A7A", year: "2021",
  },
  {
    slug: "product-branding", title: "Product Brand Identity", category: "Brand Design",
    desc: "Bloomberg wealth product branding",
    longDesc: "Bloomberg's wealth management division needed a cohesive brand identity across its product suite. The project encompassed stationery systems, digital touchpoints, and environmental branding that unified the product family under a sophisticated visual language.",
    credits: "Art direction, design",
    color: "#1A1A1A", year: "2022",
  },
];

export function getProject(slug: string): Project | undefined {
  return PROJECTS.find((p) => p.slug === slug);
}

export const GRID_ROWS_HOME: GridRow[] = [
  { type: "hero", slugs: ["battlebank"], text: [true], heights: [560] },
  { type: "wide-narrow", slugs: ["glg-brand", "glg-video"], text: [true, true], heights: [520, 380] },
  { type: "narrow-wide", slugs: ["liquidstock", "year-ahead"], text: [true, true], heights: [400, 560] },
  { type: "hero", slugs: ["tiaa"], text: [true], heights: [480] },
  { type: "wide-narrow", slugs: ["bloomberg", "employee-brand"], text: [true, true], heights: [460, 340] },
];

export const GRID_ROWS_ALL: GridRow[] = [
  ...GRID_ROWS_HOME,
  { type: "narrow-wide", slugs: ["opera", "construction"], text: [true, true], heights: [380, 520] },
  { type: "hero", slugs: ["glg-explainer"], text: [true], heights: [400] },
  { type: "hero", slugs: ["product-branding"], text: [true], heights: [480] },
];

export const CATEGORIES = [
  "All", "Identity", "Brand Design", "Systems", "Event Design", "Motion",
  "Case Study", "Fractional CD", "Cutting Room Floor",
] as const;

export const CASE_STUDIES: Record<string, CaseStudy> = {
  battlebank: {
    sections: [
      { heading: "The Challenge", body: "Battle Bank needed a visual identity that could stand up in a crowded fintech landscape while communicating trust and tenacity. The name demanded a brand that felt bold without being aggressive.", images: 2 },
      { heading: "Strategic Foundation", body: "We began with a brand audit of the competitive landscape, identifying a whitespace opportunity: most challenger banks default to either playful illustration or stark minimalism. Battle Bank could own the middle ground -- serious capability wrapped in confident energy.", images: 1 },
      { heading: "Visual System", body: "The identity centers on a custom wordmark with sharpened geometry and a supporting system of graphic devices drawn from financial charting. The color palette grounds military greens with warm neutrals and a signal accent.", images: 3 },
    ],
  },
  "glg-brand": {
    sections: [
      { heading: "A Global Platform", body: "GLG connects the world's professionals with the expertise they need. The rebrand needed to work across 25+ countries, dozens of industries, and thousands of daily interactions.", images: 2 },
      { heading: "Simplifying Complexity", body: "The previous identity was fragmented across business units. We unified everything under a single, confident design language that could flex without breaking.", images: 2 },
      { heading: "Design Language", body: "Clean typography, a rationalized color system, and a flexible grid that adapts from pitch decks to product interfaces. Every element earns its place.", images: 3 },
    ],
  },
};

export const THOUGHTS: Thought[] = [
  { slug: "brand-systems", title: "Why Brand Systems Beat Brand Guidelines", date: "Jan 2025", excerpt: "Guidelines tell you what not to do. Systems tell you how to think." },
  { slug: "fractional-cd", title: "The Case for Fractional Creative Directors", date: "Nov 2024", excerpt: "Not every company needs a full-time CD. But every brand needs creative direction." },
  { slug: "visual-storytelling", title: "Visual Storytelling in B2B", date: "Sep 2024", excerpt: "B2B doesn't have to be boring. Here's how to bring narrative to enterprise design." },
  { slug: "design-leadership", title: "Design Leadership Without the Title", date: "Jul 2024", excerpt: "You don't need to be a director to lead design thinking in your organization." },
];

export const CLIENTS = [
  "Bloomberg", "GLG", "TIAA", "Mastercard", "JPMorgan Chase", "Bank of America",
  "Deloitte", "EY", "MetLife", "Prudential", "S&P Global", "Moody's",
] as const;

