content.content:
  1→"use client";
  2→
  3→import { useState, useEffect, useCallback } from "react";
  4→import styles from "./IntroAnimation.module.css";
  5→
  6→const GRID_POSITIONS = [0, 1 / 6, 1 / 3, 1 / 2, 2 / 3, 5 / 6, 1];
  7→const SESSION_KEY = "jaime-intro-played";
  8→
  9→// Timeline (ms)
 10→const T_GRID_START = 100;
 11→const T_GRID_STAGGER = 60;
 12→const T_NAME = 800;
 13→const T_SUBTITLE = 1400;
 14→const T_DATE = 1600;
 15→const T_FADE = 2800;
 16→const T_CLEANUP = 3500;
 17→
 18→export function IntroAnimation() {
 19→  const [phase, setPhase] = useState<
 20→    "check" | "playing" | "fadeOut" | "done"
 21→  >("check");
 22→  const [gridVisible, setGridVisible] = useState(false);
 23→  const [nameVisible, setNameVisible] = useState(false);
 24→  const [subtitleVisible, setSubtitleVisible] = useState(false);
 25→  const [dateVisible, setDateVisible] = useState(false);
 26→
 27→  const skipIntro = useCallback(() => {
 28→    setPhase("done");
 29→    try {
 30→      sessionStorage.setItem(SESSION_KEY, "1");
 31→    } catch {
 32→      // sessionStorage unavailable
 33→    }
 34→  }, []);
 35→
 36→  useEffect(() => {
 37→    // Check if already played this session
 38→    try {
 39→      if (sessionStorage.getItem(SESSION_KEY)) {
 40→        setPhase("done");
 41→        return;
 42→      }
 43→    } catch {
 44→      // sessionStorage unavailable, play anyway
 45→    }
 46→
 47→    // Check reduced motion preference
 48→    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
 49→      skipIntro();
 50→      return;
 51→    }
 52→
 53→    setPhase("playing");
 54→
 55→    // Grid lines draw
 56→    const t1 = setTimeout(() => setGridVisible(true), T_GRID_START);
 57→    // Name reveals
 58→    const t2 = setTimeout(() => setNameVisible(true), T_NAME);
 59→    // Subtitle reveals
 60→    const t3 = setTimeout(() => setSubtitleVisible(true), T_SUBTITLE);
 61→    // Date fades in
 62→    const t4 = setTimeout(() => setDateVisible(true), T_DATE);
 63→    // Fade out overlay
 64→    const t5 = setTimeout(() => setPhase("fadeOut"), T_FADE);
 65→    // Remove from DOM
 66→    const t6 = setTimeout(() => {
 67→      setPhase("done");
 68→      try {
 69→        sessionStorage.setItem(SESSION_KEY, "1");
 70→      } catch {
 71→        // sessionStorage unavailable
 72→      }
 73→    }, T_CLEANUP);
 74→
 75→    return () => {
 76→      clearTimeout(t1);
 77→      clearTimeout(t2);
 78→      clearTimeout(t3);
 79→      clearTimeout(t4);
 80→      clearTimeout(t5);
 81→      clearTimeout(t6);
 82→    };
 83→  }, [skipIntro]);
 84→
 85→  if (phase === "done") return null;
 86→
 87→  return (
 88→    <div
 89→      className={`${styles.overlay} ${phase === "fadeOut" ? styles.fadeOut : ""}`}
 90→      aria-hidden="true"
 91→    >
 92→      {/* Grid lines */}
 93→      <div className={styles.gridContainer}>
 94→        <div className={styles.gridInner}>
 95→          <div className={styles.gridTrack}>
 96→            {GRID_POSITIONS.map((pos, i) => (
 97→              <div
 98→                key={i}
 99→                className={`${styles.gridLine} ${gridVisible ? styles.lineVisible : ""}`}
100→                style={{
101→                  left: `${pos * 100}%`,
102→                  animationDelay: gridVisible
103→                    ? `${i * T_GRID_STAGGER}ms`
104→                    : undefined,
105→                }}
106→              />
107→            ))}
108→          </div>
109→        </div>
110→      </div>
111→
112→      {/* Center text */}
113→      <div className={styles.content}>
114→        <div className={styles.nameMask}>
115→          <span
116→            className={`${styles.name} ${nameVisible ? styles.nameVisible : ""}`}
117→          >
118→            Jaime Ibrahim
119→          </span>
120→        </div>
121→        <div className={styles.subtitleMask}>
122→          <span
123→            className={`${styles.subtitle} ${subtitleVisible ? styles.subtitleVisible : ""}`}
124→          >
125→            Brand Design Director
126→          </span>
127→        </div>
