"use client";

import { useState } from "react";
import { CategoryFilter } from "@/components/CategoryFilter";
import { EditorialGrid } from "@/components/EditorialGrid";
import { GRID_ROWS_ALL } from "@/lib/projects";

export default function WorkPage() {
  const [filter, setFilter] = useState("All");

  return (
    <div style={{ padding: "var(--nav-h) var(--pad) clamp(48px, 6vh, 80px)" }}>
      <div style={{ maxWidth: "var(--max-w)", margin: "0 auto", padding: "clamp(48px, 10vh, 120px) 0 0" }}>
        <p
          style={{
            fontSize: "clamp(22px, 2.4vw, 34px)",
            fontWeight: 400,
            lineHeight: 1.45,
            letterSpacing: "-0.01em",
            color: "var(--text)",
            maxWidth: 580,
            margin: 0,
          }}
        >
          Selected work across brand identity, systems design, event design, and motion.
        </p>
      </div>
      <CategoryFilter active={filter} onChange={setFilter} />
      <EditorialGrid rows={GRID_ROWS_ALL} filterCategory={filter} />
    </div>
  );
}

