import styles from "./GridLines.module.css";

const POSITIONS = [0, 1 / 6, 1 / 3, 1 / 2, 2 / 3, 5 / 6, 1];

interface GridLinesProps {
  animated?: boolean;
}

export function GridLines({ animated = false }: GridLinesProps) {
  return (
    <div className={styles.container}>
      <div className={styles.inner}>
        <div className={styles.track}>
          {POSITIONS.map((pos, i) => (
            <div
              key={i}
              className={`${styles.line} ${animated ? styles.animated : ""}`}
              style={{
                left: `${pos * 100}%`,
                animationDelay: animated ? `${80 + i * 60}ms` : undefined,
              }}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

