 1→"use client";
 2→
 3→import { useMemo } from "react";
 4→import { GridCard } from "./GridCard";
 5→import { PROJECTS } from "@/lib/projects";
 6→import type { GridRow, GridRowType } from "@/lib/types";
 7→import styles from "./EditorialGrid.module.css";
 8→
 9→const PROJECT_MAP = new Map(PROJECTS.map((p) => [p.slug, p]));
10→
11→function colsFor(type: GridRowType): string {
12→  switch (type) {
13→    case "wide-narrow":
14→      return "2fr 1fr";
15→    case "narrow-wide":
16→      return "1fr 2fr";
17→    case "triple":
18→      return "1fr 1fr 1fr";
19→    default:
20→      return "1fr";
21→  }
22→}
23→
24→function responsiveClass(type: GridRowType): string {
25→  if (type === "triple") return "grid-triple";
26→  if (type === "wide-narrow" || type === "narrow-wide") return "grid-pair";
27→  return "";
28→}
29→
30→interface EditorialGridProps {
31→  rows: GridRow[];
32→  filterCategory?: string;
33→}
34→
35→export function EditorialGrid({ rows, filterCategory = "All" }: EditorialGridProps) {
36→  const filteredRows = useMemo(() => {
37→    if (filterCategory === "All") return rows;
38→    return rows
39→      .map((row) => {
40→        const filtered = row.slugs
41→          .map((slug, i) => {
42→            const p = PROJECT_MAP.get(slug);
43→            return p && p.category === filterCategory ? i : -1;
44→          })
45→          .filter((i) => i !== -1);
46→
47→        if (filtered.length === 0) return null;
48→
49→        return {
50→          ...row,
51→          type:
52→            filtered.length === 1
53→              ? ("hero" as GridRowType)
54→              : filtered.length === 2 && row.type === "triple"
55→                ? ("wide-narrow" as GridRowType)
56→                : row.type,
57→          slugs: filtered.map((i) => row.slugs[i]),
58→          text: filtered.map((i) => row.text[i]),
59→          heights: filtered.map((i) => row.heights[i]),
60→        };
61→      })
62→      .filter((row): row is GridRow => row !== null);
63→  }, [rows, filterCategory]);
64→
65→  return (
66→    <div className={styles.container}>
67→      {filteredRows.map((row, ri) => (
68→        <div
69→          key={ri}
70→          className={`${styles.row} ${responsiveClass(row.type)}`}
71→          style={{ gridTemplateColumns: colsFor(row.type) }}
72→        >
73→          {row.slugs.map((slug, si) => {
74→            const project = PROJECT_MAP.get(slug);
75→            if (!project) return null;
76→            return (
77→              <GridCard
78→                key={slug}
79→                project={project}
80→                showText={row.text[si]}
81→                height={row.heights[si]}
82→                columnIndex={si}
83→              />
84→            );
85→          })}
86→        </div>
87→      ))}
88→    </div>
89→  );
90→}
