  6→.imageContainer {
  7→  border-radius: var(--img-radius);
  8→  overflow: hidden;
  9→  position: relative;
 10→}
 11→
 12→/* Paper cutout: inset shadow layered over the image */
 13→.imageContainer::after {
 14→  content: '';
 15→  position: absolute;
 16→  inset: 0;
 17→  border-radius: var(--img-radius);
 18→  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.10);
 19→  pointer-events: none;
 20→  z-index: 2;
 21→}
 22→
 23→/* --- Domino reveal (IO-triggered) --- */
 24→
 25→.imageInner {
 26→  clip-path: inset(0 0 100% 0);
 27→  opacity: 0;
 28→  transform: scale(1.05);
 29→  transition:
 30→    clip-path 700ms var(--ease-out) var(--reveal-delay, 0ms),
 31→    opacity 600ms var(--ease-out) var(--reveal-delay, 0ms),
 32→    transform 800ms var(--ease-out) var(--reveal-delay, 0ms);
 33→}
 34→
 35→/* Reveal lands at 75% opacity — hover brings to full */
 36→.cardRevealed .imageInner {
 37→  clip-path: inset(0 0 0% 0);
 38→  opacity: 0.75;
 39→  transform: scale(1);
 40→}
 41→
 42→/* After reveal, transition to hover-ready (no stagger delay) */
 43→.cardRevealed .imageInner {
 44→  transition:
 45→    opacity 400ms var(--ease),
 46→    transform 600ms var(--ease);
 47→}
 48→
 49→/* Hover: full opacity + subtle scale inside the crop window */
 50→.card:hover .imageInner {
 51→  opacity: 1;
 52→  transform: scale(1.04);
 53→}
 54→
 55→/* --- Text block --- */
 56→
 57→.textBlock {
 58→  margin-top: 14px;
 59→  padding-bottom: 0;
 60→  opacity: 0;
 61→  transform: translateY(12px);
 62→  transition:
 63→    opacity 500ms var(--ease-out) calc(var(--reveal-delay, 0ms) + 200ms),
 64→    transform 500ms var(--ease-out) calc(var(--reveal-delay, 0ms) + 200ms);
 65→}
 66→
 67→.cardRevealed .textBlock {
 68→  opacity: 1;
 69→  transform: translateY(0);
 70→}
 71→
 72→/* --- Text styles --- */
 73→
