 86→  margin: 0 0 8px;
 87→  color: var(--muted);
 88→  letter-spacing: normal;
 89→  line-height: 1.4;
 90→}
 91→
 92→/* Elevator metatags */
 93→.metatagWrapper {
 94→  height: 30px;
 95→  overflow: hidden;
 96→  margin-top: 8px;
 97→}
