 99→.metatagInner {
100→  display: flex;
101→  flex-wrap: wrap;
102→  gap: 8px;
103→  transform: translateY(-110%);
104→  opacity: 0;
105→  transition:
106→    transform 350ms var(--ease),
107→    opacity 250ms var(--ease);
108→}
109→
110→.card:hover .metatagInner {
111→  transform: translateY(0);
112→  opacity: 1;
